-- Idempotent reference schema. Existing project has these tables already.
-- Use Supabase migration history for controlled deployments.
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,email text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.locations(id uuid primary key default gen_random_uuid(),state text not null,city text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(state,city));
create table if not exists public.jobs(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,organization text not null,job_type text not null check(job_type in('Government','Private')),state text not null,city text,education text[] not null default '{}',vacancies integer check(vacancies is null or vacancies>=0),application_start date,application_end date,salary text,qualification text,description text,official_url text,notification_url text,status text not null default 'draft' check(status in('draft','published','archived')),featured boolean not null default false,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.admin_users enable row level security;alter table public.locations enable row level security;alter table public.jobs enable row level security;
revoke execute on function public.rls_auto_enable() from public,anon,authenticated;
